// pages/guest.page.ts
// Generated by QA-AI-Framework — Playwright Automation Agent
// Module: Guest/Hunter Directory (GUEST)
// Application: IGZ Marquis Hunting App ("RanchOps Pro")
//
// Live DOM verification: docs/dom-snapshots/guest.json (2026-11-03).
// Key discrepancy vs. documentation: there is no literal "Age" field on the Guest Directory
// edit form — the documented optional "Age" field (FR-GUEST-003/TC_GUEST_011) is surfaced
// as "Date of Birth" on this screen. Street Address/City/State/ZIP are confirmed optional
// (no mandatory asterisk) on this edit form specifically.

import { Locator, Page, expect } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';
import { ConfigurationManager } from '../Framework/src/config/ConfigurationManager';

export class GuestPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  // -- Guest Directory list (/guests) --
  get guestDirectoryHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Guest Directory' });
  }

  get searchGuestsInput(): Locator {
    return this.page.getByPlaceholder('Search name, email, ranch');
  }

  get typeFilterDropdown(): Locator {
    return this.page.getByRole('combobox').filter({ hasText: 'All Types' }).first();
  }

  get ranchFilterDropdown(): Locator {
    return this.page.getByRole('combobox').filter({ hasText: 'All Ranches' }).first();
  }

  get cardViewToggleButton(): Locator {
    return this.page.getByRole('button', { name: 'Card view' });
  }

  get tableViewToggleButton(): Locator {
    return this.page.getByRole('button', { name: 'Table view' });
  }

  get guestsTable(): Locator {
    return this.page.getByRole('table');
  }

  get guestsTableColumnHeaders(): Locator {
    return this.guestsTable.getByRole('columnheader');
  }

  get emptyStateMessage(): Locator {
    return this.page.getByText(/no guests found|no results|nothing to show/i);
  }

  getGuestRowByText(text: string): Locator {
    return this.page.getByRole('row').filter({ hasText: text });
  }

  getEditButtonForRow(rowLocator: Locator): Locator {
    return rowLocator.getByRole('button', { name: 'Edit' });
  }

  // -- Guest Entry Form (within a booking's Guest Details step) --
  get guestEntryFullNameInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Full Name *' });
  }

  get guestEntryEmailInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Email Address *' });
  }

  get guestEntryAgeSpinbutton(): Locator {
    return this.page.getByRole('spinbutton', { name: 'Age' });
  }

  // -- Guest Edit Form (/guests/hunter/{id}/edit) --
  get editGuestProfileHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Edit Guest Profile' });
  }

  get backToGuestDetailsButton(): Locator {
    return this.page.getByRole('button', { name: 'Back to Guest Details' });
  }

  get editFullNameInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Enter full name' });
  }

  get editEmailInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Enter email address' });
  }

  get editPhoneInput(): Locator {
    return this.page.getByRole('textbox').filter({ hasText: '+1' }).first();
  }

  get editSmsConsentCheckbox(): Locator {
    return this.page.getByRole('checkbox', { name: 'SMS consent' });
  }

  get editDateOfBirthButton(): Locator {
    return this.page.getByRole('button', { name: 'Date of Birth' });
  }

  get editAddressInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Address' });
  }

  get editCityInput(): Locator {
    return this.page.getByRole('textbox', { name: 'City' });
  }

  get editStateInput(): Locator {
    return this.page.getByRole('textbox', { name: 'State' });
  }

  get editZipInput(): Locator {
    return this.page.getByRole('textbox', { name: 'ZIP Code' });
  }

  get editEmergencyContactNameInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Contact Name' });
  }

  get editRelationshipInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Relationship' });
  }

  get editLicenseNumberInput(): Locator {
    return this.page.getByRole('textbox', { name: 'Enter license number' });
  }

  get cancelEditButton(): Locator {
    return this.page.getByRole('button', { name: 'Cancel' });
  }

  get saveChangesButton(): Locator {
    return this.page.getByRole('button', { name: 'Save Changes' });
  }

  // -- Pagination (see platform.page.ts for shared helpers; exposed here for convenience) --
  get paginationSummaryText(): Locator {
    return this.page.getByText(/Showing \d+ to \d+ of \d+ results/);
  }

  // ==================== Validations ====================

  async assertGuestDirectoryLoaded(): Promise<void> {
    await expect(this.guestDirectoryHeading).toBeVisible();
    await expect(this.guestsTable).toBeVisible();
  }

  async assertColumnHeadersMatch(expectedHeaders: string[]): Promise<void> {
    const actual = await this.guestsTableColumnHeaders.allTextContents();
    expect(actual.map((h) => h.trim())).toEqual(expectedHeaders);
  }

  async assertNoMandatoryIndicator(labelText: string): Promise<void> {
    await expect(this.page.locator(`text=${labelText}`).locator('..').getByText('*')).toHaveCount(0);
  }

  async assertEditGuestFormLoaded(): Promise<void> {
    await expect(this.editGuestProfileHeading).toBeVisible();
  }

  async assertEmptyStateVisible(): Promise<void> {
    await expect(this.emptyStateMessage).toBeVisible();
  }

  async assertNoHorizontalOverflow(): Promise<void> {
    const hasOverflow = await this.page.evaluate(
      () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
    );
    expect(hasOverflow).toBeFalsy();
  }

  // ==================== Actions ====================

  /** Deep-links directly to the Guest Directory list — confirmed render-safe once authenticated (see guest.json). */
  async navigateToGuestDirectory(): Promise<void> {
    await this.logInfo('Navigating to Guest Directory');
    await this.page.goto(`${ConfigurationManager.config().baseUrl}/guests`);
    await this.waitForLoadingToComplete();
  }

  async searchGuests(term: string): Promise<void> {
    await this.withHeal(this.searchGuestsInput, (l) => l.fill(term), 'Search Guests Input');
  }

  async switchToCardView(): Promise<void> {
    await this.withHeal(this.cardViewToggleButton, (l) => l.click(), 'Card View Toggle');
  }

  async switchToTableView(): Promise<void> {
    await this.withHeal(this.tableViewToggleButton, (l) => l.click(), 'Table View Toggle');
  }

  async openGuestByRowText(text: string): Promise<void> {
    const row = this.getGuestRowByText(text);
    await this.withHeal(row, (l) => l.click(), `Guest Row (${text})`);
    await this.waitForLoadingToComplete();
  }

  async editGuestByRowText(text: string): Promise<void> {
    const row = this.getGuestRowByText(text);
    const editButton = this.getEditButtonForRow(row);
    await this.withHeal(editButton, (l) => l.click(), `Edit Button (${text})`);
    await this.waitForLoadingToComplete();
  }

  async updateGuestProfile(details: {
    fullName?: string;
    email?: string;
    address?: string;
    city?: string;
    state?: string;
    zip?: string;
  }): Promise<void> {
    if (details.fullName) await this.withHeal(this.editFullNameInput, (l) => l.fill(details.fullName as string), 'Edit Full Name Input');
    if (details.email) await this.withHeal(this.editEmailInput, (l) => l.fill(details.email as string), 'Edit Email Input');
    if (details.address) await this.withHeal(this.editAddressInput, (l) => l.fill(details.address as string), 'Edit Address Input');
    if (details.city) await this.withHeal(this.editCityInput, (l) => l.fill(details.city as string), 'Edit City Input');
    if (details.state) await this.withHeal(this.editStateInput, (l) => l.fill(details.state as string), 'Edit State Input');
    if (details.zip) await this.withHeal(this.editZipInput, (l) => l.fill(details.zip as string), 'Edit ZIP Input');
  }

  async saveChanges(): Promise<void> {
    await this.logInfo('Saving guest profile changes');
    await this.withHeal(this.saveChangesButton, (l) => l.click(), 'Save Changes Button');
    await this.logSuccess('Guest profile saved');
  }

  async cancelEdit(): Promise<void> {
    await this.withHeal(this.cancelEditButton, (l) => l.click(), 'Cancel Edit Button');
  }
}
